def _matches_any_glob(rel_posix: str, globs: list[str]) -> bool:
    from fnmatch import fnmatch

    for g in globs:
        if fnmatch(rel_posix, g) or fnmatch(rel_posix, g.lstrip("./")):
            return True
    return False

